=== table.html ===
<div class="table-responsive">
    {% if name %}
        <p class="h4 item-header">{{ name }}</p>
    {% endif %}
    {% if rows | length > 0 %}
        <table class="table table-striped">
            {% if rows[0]['value'].__class__.__name__ == 'list' %}
                <thead>
                    <tr>
                        <th>&nbsp;</th>
                        {% for v in rows[0]['value'] %}
                            <th style="white-space: pre; color: {{ style.primary_colors[loop.index0] }};">{{ style._labels[loop.index0] }}</th>
                        {% endfor %}
                    </tr>
                </thead>
            {% endif %}
            <tbody>
                {% for row in rows %}
                    <tr{% if 'alert' in row and row['alert'] %} class="alert-info"{% endif %}>
                        <th>{{ row['name'] }}</th>
                        {% if row['value'].__class__.__name__ == 'list' %}
                            {% for value in row['value'] %}
                                <td style="white-space: nowrap;">{{ value }}{% if loop.last and 'hint' in row %} {{ row['hint'] }}{% endif %}</td>
                            {% endfor %}
                        {% else %}
                            <td style="white-space: nowrap;">{{ row['value'] }}{% if 'hint' in row %} {{ row['hint'] }}{% endif %}</td>
                        {% endif %}
                    </tr>
                {% endfor %}
            </tbody>
        </table>
    {% endif %}
    {% if caption %}
        <div class="caption text-center text-body-secondary">
            {{ caption }}
        </div>
    {% endif %}
</div>=== scores.html ===
<style>
  .progress {
    height: 18px;
    border-radius: 6px;
    font-size: 0.9rem;
  }

  .overall-score {
    font-size: 2.5rem;
  }

  .metric-subtitle {
    font-size: 0.9rem;
    color: #6c757d;
  }

  .dual-metric {
    display: flex;
    justify-content: space-around;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
  }

  .dual-metric .metric {
    min-width: 120px;
  }

  .card.metric-card {
      min-height: 105px; /* Maior altura mínima do cartão */
  }
</style>

<div class="container my-5">
  <!-- Overall Score -->
  <div class="row justify-content-center text-center mb-sm-3">
    <div class="col-12">
        <div class="card shadow-sm p-4">
          <h5 class="text-muted mb-3">Overall Data Quality Score</h5>
          <div class="dual-metric">
            {% for i in range(overall_score | length) %}
              <div class="metric">
                {% if overall_score | length > 1 %}
                <div class="metric-subtitle">{{ name[i]}}</div>
                {% endif %}
                <div class="overall-score fw-bold" style="color: {{ style.primary_color }}">{{ overall_score[i]}}</div>
              </div>
            {% endfor %}
          </div>
        </div>
    </div>
  </div>

  <!-- Metrics -->
    <div class="row g-4 text-center">
    {% for metric in items %}
      <div class="col-lg-4 col-md-6 col-sm-12">
        <div class="card shadow-sm p-3 h-100 metric-card">
          <div class="h6 text-muted mb-2">{{ metric.name }}</div>
          {% for j in range(metric.submetrics| length) %}
            {% if metric.submetrics | length > 1 %}
              <div class="metric-subtitle text-start">{{ name[j] }}</div>
            {% endif %}
            <div class="progress mb-2 bg-light">
              <div
                class="progress-bar"
                style="width: {{ metric.submetrics[j].value  }}%; background-color: {{ metric.submetrics[j].color}};">
                {{ metric.submetrics[j].value }}%
              </div>
            </div>
          {% endfor %}
        </div>
      </div>
    {% endfor %}
  </div>
</div>


